#include <stdio.h>
int main(void){
    int n=5;
    int adj[5][5]={0};
    int e[][2]={{0,1},{1,2},{2,3},{3,4},{4,0}};  /* 5-环：每个顶点度数为 2 */
    int m=5;
    for(int k=0;k<m;k++){ adj[e[k][0]][e[k][1]]=1; adj[e[k][1]][e[k][0]]=1; }
    int ok=1;
    for(int i=0;i<n;i++){
        int d=0; for(int j=0;j<n;j++) d+=adj[i][j];
        if(d%2){ ok=0; printf("deg(%d)=%d odd\n", i, d); }
    }
    printf(ok ? "eulerian: yes\n" : "eulerian: no\n");
    return 0;
}
